// Expects body: { post, platforms:["linkedin",...], mediaUrls?, scheduleDate?,
//   youTubeOptions?, pinterestOptions?, idempotencyKey?, notes? }
// Passes through to Ayrshare, dropping empty fields.
const b = $json.body || $json;
const out = { post: b.post ?? '', platforms: b.platforms };
if (Array.isArray(b.mediaUrls) && b.mediaUrls.length) out.mediaUrls = b.mediaUrls;
if (b.scheduleDate) out.scheduleDate = b.scheduleDate;
if (b.idempotencyKey) out.idempotencyKey = b.idempotencyKey;
if (b.notes) out.notes = b.notes;
if (b.youTubeOptions) out.youTubeOptions = b.youTubeOptions;
if (b.pinterestOptions) out.pinterestOptions = b.pinterestOptions;
return [{ json: out }];
